# libc.map — libc.so 导出符号版本脚本
#
# 规则：头文件即契约 + 跨 .so 引用。
#   - global: user/include/** 下声明且 libc.so 实际定义的符号，全部导出
#   - 必要的 __ 事实 ABI 符号（crt0/assert/errno 跨 .so 调用）显式列入
#   - local: *; 兜底：所有未列入 global 的符号（内部实现、_Z mangled、
#     __libc_run_*、__pthread_key_*、kvfmt_*、atexit_* 等）一律 hidden
#
# 单版本节点 LIBC_1.0；将来 Proton 二进制兼容需要符号版本时加 GLIBC_2.x 节点。

LIBC_1.0 {
global:
    /* <stdio.h> — musl upstream src/stdio (musl_stdio_objs, stdio.md). FILE is
     * musl's struct _IO_FILE; the full narrow-char stdio family now ships:
     * printf/scanf engines + wrappers, byte getc/putc family + *_unlocked,
     * fopen/fclose/fread/fwrite/fseek/ftell + fseeko/ftello, getdelim/getline,
     * open_memstream/fmemopen/fopencookie, flockfile/..., asprintf/vasprintf.
     * stdin/stdout/stderr are OBJECT symbols (musl stdin.c/stdout.c/stderr.c).
     * Deliberately NOT exported (stay hidden under local: *;):
     *   rename        — in musl_unistd_objs (unistd block below), not re-listed here
     *   dprintf/vdprintf — musl native stdio impl (routes through vfprintf); not
     *                   public. The loader resolves to them but no app consumer
     *                   needs them exported.
     *   tmpfile/tmpnam/tempnam — NOW exported (their __randname → __clock_gettime
     *                   dep is satisfied since the time module migrated; same
     *                   blocker as stdlib mkstemp, todo.md:344/379/391).
     *   __isoc99_x / _IO_x / __getdelim / x_used — internal aliases (weak_alias), no
     *                   consumer references them (not declared in <stdio.h>)
     *   wide-char w* family (fwprintf/fgetwc/wscanf/...) — NOW exported under the
     *                   <wchar.h> block below (musl_stdio_objs compiles them; deps
     *                   satisfied by musl_wchar_objs + musl_time_objs). Only the
     *                   *_unlocked and __isoc99_* aliases stay hidden here. */
    asprintf; clearerr; clearerr_unlocked; ctermid; fclose; fdopen; feof;
    feof_unlocked; ferror; ferror_unlocked; fflush; fflush_unlocked; fgetc;
    fgetc_unlocked; fgetln; fgetpos; fgets; fgets_unlocked; fileno;
    fileno_unlocked; flockfile; fmemopen; fopen; fopen64; fopencookie; fprintf; fputc;
    fputc_unlocked; fputs; fputs_unlocked; fread; fread_unlocked; freopen;
    fscanf; fseek; fseeko; fsetpos; ftell; ftello; ftrylockfile; funlockfile;
    fwrite; fwrite_unlocked; getc; getchar; getchar_unlocked; getc_unlocked;
    getdelim; getline; gets; getw; open_memstream; perror; printf; putc;
    putchar; putchar_unlocked; putc_unlocked; puts; putw; remove; rewind;
    scanf; setbuf; setbuffer; setlinebuf; setvbuf; snprintf; sprintf; sscanf;
    stdin; stdout; stderr; ungetc; vasprintf; vfprintf; vfscanf; vprintf;
    vscanf; vsnprintf; vsprintf; vsscanf;
    popen; pclose;
    tmpfile; tmpnam; tempnam;

    /* <stdlib.h> — pure compute + startup/env/exit chain from musl_stdlib_objs
     * (stdlib.md). abs/labs/llabs/imaxabs/imaxdiv/div/ldiv/lldiv, atoi/atol/
     * atoll, strtol/strtoul/strtoll/strtoull/strtoimax/strtoumax, strtod/strtof/
     * strtold/atof, qsort/bsearch, rand/srand/rand_r, getenv/setenv/putenv/
     * unsetenv/clearenv/environ, exit/atexit/abort/quick_exit/at_quick_exit/
     * _Exit, __libc_start_main all come from musl upstream now. */
    abs; atexit; atoi; atol; atoll; calloc; exit; free; labs; llabs;
    malloc; qsort; bsearch; rand; rand_r; realloc; srand; strtol; strtoul;
    strtoll; strtoull; strtod; strtof; strtold; atof; div; ldiv; lldiv;
    imaxabs; imaxdiv; strtoimax; strtoumax;
    getenv; setenv; putenv; unsetenv; clearenv; environ; secure_getenv;
    _Exit; quick_exit; at_quick_exit; __cxa_atexit; __cxa_finalize;
    /* aligned allocation family — musl src/malloc/{aligned_alloc,memalign,
     * posix_memalign,reallocarray}.c (musl_malloc_objs). C11 aligned_alloc +
     * the posix/gnu companions; needed by C++ runtimes (libc++abi's operator
     * new(std::align_val_t) routes to aligned_alloc) and by cross-built
     * consumers that link -lc. */
    aligned_alloc; memalign; posix_memalign; reallocarray;
    mkstemp; mktemp; mkstemps; realpath;

    /* <syslog.h> -- musl src/misc/syslog.c (musl_misc_objs). */
    closelog; openlog; setlogmask; syslog; vsyslog;

    /* <stdlib.h> / <unistd.h> / <pty.h> / <ftw.h> / <mntent.h> / <wordexp.h> /
     * <fmtmsg.h> / <sys/auxv.h> -- the rest of musl src/misc (musl_misc_objs),
     * migrated as a glob+exclude (see modules/misc.cmake). Excluded files'
     * symbols (getresuid/getresgid/setdomainname/initgroups, whose routed
     * syscalls the kernel does not implement) are deliberately NOT exported.
     * basename/dirname/ffs are exported in the <string.h>/<strings.h> blocks
     * above; realpath/getpriority/setpriority/getrlimit/setrlimit/getrusage/
     * syscall/ioctl/uname are exported in their family blocks below. */
    a64l; l64a;
    fmtmsg;
    forkpty; openpty; login_tty;
    /* POSIX pty master-allocation family (src/misc/pty.c). posix_openpt/
     * grantpt/unlockpt are public <stdlib.h> symbols that musl leaves at
     * default visibility (hidden by local:* unless listed here). */
    posix_openpt; grantpt; unlockpt;
    getauxval;
    get_current_dir_name;
    getdomainname;
    gethostid;
    /* getopt() + getopt_long() (functions) and their global state variables
     * (src/misc/getopt.c): optarg/optind/opterr/optopt are data symbols the
     * application reads/writes, so they must be exported too (local:* would
     * hide them and break every getopt consumer under dynamic linking). */
    getopt; getopt_long;
    optarg; optind; opterr; optopt;
    getsubopt;
    issetugid;
    lockf;
    setmntent; getmntent; addmntent; endmntent; hasmntopt;
    nftw; ftw;
    ptsname; ptsname_r;
    wordexp; wordfree;

    /* GNU <errno.h> startup-name variables, initialized by musl
     * __libc_start_main and defined in src/internal/libc.c. */
    program_invocation_name; program_invocation_short_name;

    /* <string.h> — musl upstream (src/string/* + x86_64 asm memcpy/memmove/memset
     * + src/misc basename). The extension symbols musl compiles but we do NOT
     * list here (stpncpy/memrchr/strsep/strlcpy/strlcat/memccpy/mempcpy/
     * strchrnul/strcasestr/strverscmp/ffsl/ffsll/swab) are intentionally
     * unexported — `local: *;` hides them from the dynsym. strcoll/strxfrm/
     * strcoll_l/strxfrm_l live in src/locale/ (built + exported by the
     * <locale.h> block below — musl_locale_objs); strcasecmp_l/strncasecmp_l
     * are still NOT compiled (musl has them in src/locale/strcasecmp_l.c,
     * 0 callers, out of the locale tier's scope) so they stay declare-only.
     * stpcpy IS exported (Mesa vtn_opencl.c's stpcpy path links against it). */
    bzero; bcmp; bcopy; index; rindex; memcmp; memcpy; memmove; memset;
    memchr; memmem; strcat; strchr; strcmp; strcpy; strcspn; strdup;
    strerror; strerror_r; strerror_l; strlen; strncat; strncmp; strncpy; strndup;
    stpcpy;
    strpbrk; strrchr; strspn; strstr; strtok; strtok_r;
    strverscmp;
    /* strsignal — musl src/string/strsignal.c, built in musl_signal_objs (not
     * musl_string_objs, which excludes it); psignal depends on it. Declared by
     * <string.h> under _GNU_SOURCE. */
    strsignal;
    basename;
    dirname;

    /* <regex.h> + <fnmatch.h> - musl src/regex. glob/globfree stay excluded:
     * GLOB_TILDE needs getpwnam_r/getpwuid_r, now migrated (src/passwd module),
     * but glob.c is deliberately left for a follow-up so the passwd migration
     * ships/testable in isolation (see passwd section in doc/design/todo.md). */
    regcomp; regexec; regerror; regfree;
    fnmatch;

    /* <pwd.h> + <grp.h> + <shadow.h> - musl src/passwd (passwd_worklist).
     * Whole-directory glob; reads /etc/passwd /etc/group /etc/shadow via stdio
     * + nscd AF_UNIX fallback (no syscalls of its own). getgrouplist here;
     * initgroups stays in src/misc (excluded — needs SYS_setgroups). */
    getpwnam; getpwuid; getpwnam_r; getpwuid_r;
    getpwent; setpwent; endpwent;
    getgrnam; getgrgid; getgrnam_r; getgrgid_r;
    getgrent; setgrent; endgrent;
    getgrouplist;
    getspnam; getspnam_r; getspent; setspent; endspent;
    fgetpwent; putpwent; fgetgrent; putgrent; fgetspent; putspent;
    lckpwdf; ulckpwdf;

    /* <strings.h> */
    ffs; strcasecmp; strncasecmp;

    /* <unistd.h> */
    access; faccessat; eaccess; euidaccess; close; dup; dup2; _exit; ftruncate; getcwd; getpid; gettid;
    ioperm; isatty; lseek; memfd_create; mkdir; open; open64; pipe; pipe2; pread; read;
    rmdir; sleep; ttyname; ttyname_r; unlink; unlinkat; rename; renameat;
    usleep; write;
    sendfile; /* <sys/sendfile.h> — musl src/linux/sendfile.c, thin SYS_sendfile wrapper. */
    chdir; fchdir;
    utimensat;
    symlink; symlinkat; readlinkat;
    link; linkat;
    getuid; geteuid; getgid; getegid; getppid; getpgrp; umask;
    gethostname; sethostname; alarm; pause;
    setitimer;
    truncate; fsync; fdatasync; sync;
    getpagesize; sysconf;
    pathconf; fpathconf;
    nice; getpriority; setpriority;
    chown; fchown; fchownat; lchown; readlink;
    getlogin;
    /* M1.1 — set*id ladder + getgroups (unistd.md §2.A1/A2). */
    setresuid; setresgid; setreuid; setregid; seteuid; setegid; getgroups;

    /* <fcntl.h> */
    openat; fcntl; fcntl64; posix_fallocate; creat;

    /* <sys/file.h> */
    flock;

    /* <sys/uio.h> */
    preadv; readv; writev;

    /* <sys/socket.h> */
    accept4;
    socket; socketpair; accept; connect; bind; listen; shutdown;
    getsockname; getpeername; getsockopt; setsockopt;
    send; recv; sendto; recvfrom; sendmsg; recvmsg;

    /* <ctype.h> — musl src/ctype/{isalnum,isalpha,isblank,iscntrl,isdigit,
     * isgraph,islower,isprint,ispunct,isspace,isupper,isxdigit,tolower,toupper,
     * isascii,toascii}.c (musl_ctype_objs, narrow set). The _l variants are
     * weak_alias(__<fn>_l, <fn>_l) per file; both plain + _l need entries to
     * export. The wide isw / wctype set is in musl_wchar_objs (see below). */
    isalnum; isalpha; isascii; isblank; iscntrl; isdigit; isgraph;
    islower; isprint; ispunct; isspace; isupper; isxdigit; tolower;
    toupper;
    isalnum_l; isalpha_l; isblank_l; iscntrl_l; isdigit_l; isgraph_l;
    islower_l; isprint_l; ispunct_l; isspace_l; isupper_l; isxdigit_l;
    tolower_l; toupper_l;

    /* <math.h> + <fenv.h> — musl src/math + src/fenv merged into libc (musl single-libc philosophy; libm.so is an empty -lm stub). */
    fesetround; fegetexceptflag; fesetexceptflag; feholdexcept; feupdateenv;
    __flt_rounds;
    acos;
    acosf;
    acosh;
    acoshf;
    acoshl;
    acosl;
    asin;
    asinf;
    asinh;
    asinhf;
    asinhl;
    asinl;
    atan;
    atan2;
    atan2f;
    atan2l;
    atanf;
    atanh;
    atanhf;
    atanhl;
    atanl;
    cbrt;
    cbrtf;
    cbrtl;
    ceil;
    ceilf;
    ceill;
    copysign;
    copysignf;
    copysignl;
    cos;
    cosf;
    cosh;
    coshf;
    coshl;
    cosl;
    drem;
    dremf;
    erf;
    erfc;
    erfcf;
    erfcl;
    erff;
    erfl;
    exp;
    exp10;
    exp10f;
    exp10l;
    exp2;
    exp2f;
    exp2l;
    expf;
    expl;
    expm1;
    expm1f;
    expm1l;
    fabs;
    fabsf;
    fabsl;
    fdim;
    fdimf;
    fdiml;
    feclearexcept;
    fegetenv;
    fegetround;
    feraiseexcept;
    fesetenv;
    fetestexcept;
    finite;
    finitef;
    floor;
    floorf;
    floorl;
    fma;
    fmaf;
    fmal;
    fmax;
    fmaxf;
    fmaxl;
    fmin;
    fminf;
    fminl;
    fmod;
    fmodf;
    fmodl;
    frexp;
    frexpf;
    frexpl;
    hypot;
    hypotf;
    hypotl;
    ilogb;
    ilogbf;
    ilogbl;
    j0;
    j0f;
    j1;
    j1f;
    jn;
    jnf;
    ldexp;
    ldexpf;
    ldexpl;
    lgamma;
    lgammaf;
    lgammaf_r;
    lgammal;
    lgammal_r;
    lgamma_r;
    llrint;
    llrintf;
    llrintl;
    llround;
    llroundf;
    llroundl;
    log;
    log10;
    log10f;
    log10l;
    log1p;
    log1pf;
    log1pl;
    log2;
    log2f;
    log2l;
    logb;
    logbf;
    logbl;
    logf;
    logl;
    lrint;
    lrintf;
    lrintl;
    lround;
    lroundf;
