    round;
    roundf;
    roundl;
    scalb;
    scalbf;
    scalbln;
    scalblnf;
    scalblnl;
    scalbn;
    scalbnf;
    scalbnl;
    signgam;
    significand;
    significandf;
    sin;
    sincos;
    sincosf;
    sincosl;
    sinf;
    sinh;
    sinhf;
