    /* <time.h> — musl upstream (src/time/* + src/locale/langinfo.c via
     * musl_time_objs, time.md). clock_getres, clock_getcpuclockid, times
     * have no kernel syscall impl and return -ENOSYS (0 callers). The timer
     * family is NOT built (deferred, see todo.md). wcsftime IS built (in
     * musl_wchar_objs — see the <wchar.h> block below; its time deps resolve
     * via the merged libc).
     * timespec_to_tm (repo non-std) is deleted. */
    clock; clock_gettime; clock_settime; clock_getres; clock_getcpuclockid;
    ctime; ctime_r; asctime; asctime_r;
    difftime; clock_nanosleep; gettimeofday; gmtime; gmtime_r; localtime;
    localtime_r; mktime; timegm; nanosleep; strftime; strftime_l; strptime;
    time; timespec_get; times; utime; ftime; getdate; getdate_err;
    timezone; daylight; tzname; tzset;

    /* <langinfo.h> — C-locale provider compiled into musl_time_objs
     * (src/locale/langinfo.c) for __asctime/strftime/strptime. */
    nl_langinfo; nl_langinfo_l;

    /* <signal.h> */
    kill; raise; sigaction; signal; sigreturn; sigprocmask; sigpending; abort;
    sigaltstack;
    /* sigset_t helpers from musl src/signal/*.c (128-byte sigset_t) */
    sigemptyset; sigfillset; sigaddset; sigdelset; sigismember;
    /* SIGRTMIN/SIGRTMAX macros expand to these (musl private, exported for dyn ELF) */
    __libc_current_sigrtmin; __libc_current_sigrtmax;
    /* Safe musl signal additions (musl_signal_objs): pure-userspace or thin-
     * syscall sources NOT defined in user/lib/signal.cc. sigaction/sigprocmask
     * they call route to the repo's musl_glue::__libc_sigaction adapter.
     * sigwait/sigwaitinfo/sigtimedwait/sigqueue/sigsuspend/sigpause are NOT
     * exported — they need SYS_rt_sigtimedwait/queueinfo/suspend the kernel
     * lacks (deferred, doc/design/todo.md). */
    killpg; sigorset; sigandset; sigisemptyset;
    sighold; sigignore; siginterrupt; sigrelse; sigset;
    siglongjmp; getitimer; psignal; psiginfo;

    /* <termios.h> */
    tcgetattr; tcsetattr; tcgetpgrp; tcsetpgrp;

    /* <dirent.h> */
    closedir; opendir; readdir; scandir;
    telldir; seekdir; rewinddir; dirfd; readdir_r;
    fdopendir; alphasort; versionsort; posix_getdents; getdents;

    /* <sys/resource.h> */
    getrlimit; setrlimit; getrusage; prlimit;

    /* <spawn.h> */
    posix_spawn; posix_spawnp;
    posix_spawnattr_init; posix_spawnattr_destroy;
    posix_spawnattr_setflags; posix_spawnattr_getflags;
    posix_spawnattr_setpgroup; posix_spawnattr_getpgroup;
    posix_spawnattr_setsigmask; posix_spawnattr_getsigmask;
    posix_spawnattr_setsigdefault; posix_spawnattr_getsigdefault;
    posix_spawnattr_setschedparam; posix_spawnattr_getschedparam;
    posix_spawnattr_setschedpolicy; posix_spawnattr_getschedpolicy;
    posix_spawn_file_actions_init; posix_spawn_file_actions_destroy;
    posix_spawn_file_actions_addopen; posix_spawn_file_actions_addclose;
    posix_spawn_file_actions_adddup2; posix_spawn_file_actions_addchdir_np;
    posix_spawn_file_actions_addfchdir_np;

    /* <errno.h> */
    __errno_location;

    /* <assert.h> */
    __assert_fail;

    /* <setjmp.h> */
    setjmp; longjmp; _setjmp; _longjmp;

    /* <locale.h> — musl upstream (musl_locale_objs, src/locale/*). The 6 POSIX
     * locale managers + 4 collate functions (each + its _l weak_alias). All
     * pure-userspace, no kernel syscall; all collapse to the C locale at
     * runtime (no .mo catalog / no iconv in this OS — same C-locale policy as
     * strerror/langinfo). 0 in-tree callers; exported per the ctype/string/
     * wchar "export caller-less POSIX symbols" precedent so Mesa/libinput/
     * Proton-style consumers link cleanly. Scope decided via AskUserQuestion
     * (full POSIX locale management + collate). NOT exported (out of scope,
     * 0 callers, i18n-heavy): iconv/iconv_close, gettext family (textdomain/
     * bind_textdomain_codeset/dcngettext), strfmon, pleval.
     * strtof_l/strtod_l/strtold_l ARE now exported: libc++'s locale
     * __num_get_float calls them (they ignore the locale arg and delegate to
     * the plain strtof/strtod/strtold). strcoll/strxfrm/wcscoll/wcsxfrm are
     * also declared by <string.h>/<wchar.h> (see those blocks) but owned +
     * exported here. catopen/catgets/catclose ARE now exported: libc++'s
     * std::messages facet (do_open/do_get/do_close) calls them; musl catopen
     * returns (nl_catd)-1 when no catalog is found, so the C-locale no-catalog
     * policy holds at runtime. */
    setlocale; localeconv;
    newlocale; duplocale; freelocale; uselocale;
    strcoll; strcoll_l; strxfrm; strxfrm_l;
    wcscoll; wcscoll_l; wcsxfrm; wcsxfrm_l;
    strtof_l; strtod_l; strtold_l;
    __ctype_get_mb_cur_max;
    catopen; catgets; catclose;

    /* <sched.h> */
    sched_get_priority_max; sched_get_priority_min;
    sched_getaffinity; sched_getcpu; sched_getparam; sched_getscheduler;
    sched_rr_get_interval; sched_setaffinity; sched_setparam;
    sched_setscheduler; sched_yield; __sched_cpucount;

    /* <pthread.h> */
    pthread_attr_destroy; pthread_attr_getdetachstate;
    pthread_attr_getguardsize; pthread_attr_getstack;
    pthread_attr_getstacksize; pthread_attr_init;
    pthread_attr_setdetachstate; pthread_attr_setguardsize;
    pthread_attr_setstack; pthread_attr_setstacksize;
    pthread_barrier_destroy; pthread_barrier_init; pthread_barrier_wait;
    pthread_cancel;
    pthread_getaffinity_np; pthread_setaffinity_np;
    /* pthread_cleanup_push/pop are macros in musl <pthread.h>, not symbols */
    pthread_cond_broadcast; pthread_cond_destroy; pthread_cond_init;
    pthread_cond_signal; pthread_cond_wait; pthread_cond_timedwait;
    /* Condition attributes are pure user-space state. EGL creates a monotonic
     * fence condition variable and therefore needs init + setclock at link time. */
    pthread_condattr_destroy; pthread_condattr_init; pthread_condattr_setclock;
    pthread_condattr_setpshared;
    pthread_create; pthread_detach;
    pthread_equal; pthread_exit; pthread_getspecific; pthread_join;
    pthread_key_create; pthread_kill;
    pthread_mutexattr_destroy; pthread_mutexattr_gettype;
    pthread_mutexattr_init; pthread_mutexattr_settype;
    pthread_mutex_destroy; pthread_mutex_init; pthread_mutex_lock;
    pthread_mutex_timedlock; pthread_mutex_trylock; pthread_mutex_unlock;
    pthread_once; pthread_rwlock_destroy; pthread_rwlock_init;
    pthread_rwlock_rdlock; pthread_rwlock_unlock; pthread_rwlock_wrlock;
    pthread_self; pthread_setcancelstate; pthread_setcanceltype;
    pthread_setname_np; pthread_setspecific; pthread_sigmask;
    pthread_setschedparam; pthread_getschedparam; pthread_getcpuclockid;
    pthread_testcancel;

    /* TLS — musl src/thread/__tls_get_addr.c (musl_pthread). __tls_get_addr is
     * the Itanium C++ ABI TLS-access helper (emitted by clang for
     * thread_local with dynamic-initialization TLS models); libc++abi's
     * __cxa_thread_atexit / per-thread static dtors reference it. A __-prefixed
     * ABI symbol, exported because cross-built C++ runtimes link against it. */
    __tls_get_addr;

    /* <threads.h> — C11 threads. musl src/thread/{thrd,mtx,cnd,tss,call_once}_*.c
     * are pulled in by the src/thread/*.c glob in pthread.cmake (they alias the
     * pthread implementation: thrd_current/tss_get/thrd_detach are weak_alias of
     * __pthread_self_internal/__pthread_getspecific/__pthread_detach). thrd_equal
     * is a macro in musl <threads.h>, so it is not a symbol. */
    call_once;
    cnd_broadcast; cnd_destroy; cnd_init; cnd_signal; cnd_timedwait; cnd_wait;
    mtx_destroy; mtx_init; mtx_lock; mtx_timedlock; mtx_trylock; mtx_unlock;
    thrd_create; thrd_current; thrd_detach; thrd_exit; thrd_join;
    thrd_sleep; thrd_yield;
    tss_create; tss_delete; tss_get; tss_set;

    /* <sys/stat.h> */
    fstat; fstatat; lstat; lstat64; mkdir; mkdirat; mknod; stat; statx;
    chmod; fchmod; fchmodat;

    /* <sys/statvfs.h> — src/stat/statvfs.c. libc++ filesystem::__space. */
    statvfs; fstatvfs;

    /* <sys/wait.h> — musl src/process/{wait,waitpid,waitid}.c. musl folds
     * wait4 into waitpid (no standalone wait4.c), so wait4 is not a symbol. */
    waitpid; wait; waitid;

    /* <sys/mman.h> — musl upstream (src/mman/*.c via musl_mman_objs) + the
     * retained hand-written memfd_create (musl src/mman has none). mmap64 is
     * NOT a symbol: musl's <sys/mman.h> does `#define mmap64 mmap` (LFS
     * alias), so every mmap64 call site rewrites to mmap at preprocess time
     * and no object exports mmap64 — listing it here made the export check
     * fail under v1.2.6 (it was tolerated earlier only because a prior build
     * path defined it). msync/madvise/mlock/mlockall/munlock/munlockall/
     * mincore have no kernel handler (the syscall dispatch returns -ENOSYS)
     * but the symbols are exported so callers link; they return -1/ENOSYS at
     * runtime (POSIX-symbol-present / kernel-feature-absent middle state,
     * doc/design/todo.md). remap_file_pages is NOT built (musl mremap.c does
     * not define it). */
    memfd_create; mmap; munmap; mprotect; mremap; msync;
    madvise; posix_madvise; mincore;
    mlock; munlock; mlockall; munlockall;
    shm_open; shm_unlink;

    /* <sys/shm.h> — SysV SHM wrappers. The kernel currently returns ENOSYS;
     * callers such as Mesa detect that and fall back to private allocation. */
    shmat; shmctl; shmdt; shmget;

    /* <uchar.h> — musl src/multibyte/{c16,c32}{rtomb,rtoc16,rtoc32}.c (thin
     * wrappers over wcrtomb/mbrtowc in musl_multibyte_objs). C11 char16_t/
     * char32_t conversion. */
    c16rtomb; mbrtoc16; c32rtomb; mbrtoc32;

    /* <wctype.h> — musl src/ctype/{isw*,iswctype,wctrans,towctrans,wcwidth,
     * wcswidth}.c. Pure compute; locale_t pass-through (the _l variants forward
     * to the non-_l). The narrow ctype set (isalnum/tolower/...) is built in
     * musl_ctype_objs (see the <ctype.h> block above), NOT here. iswdigit is
     * both a real function (iswdigit.c) and a macro in <wchar.h>/<wctype.h>;
     * the symbol is exported (the macro shadows it for C callers). */
    iswalnum; iswalpha; iswblank; iswcntrl; iswdigit; iswgraph; iswlower;
    iswprint; iswpunct; iswspace; iswupper; iswxdigit;
    iswctype; wctype; wctrans; towctrans; towlower; towupper;
    wcwidth; wcswidth;
    iswalnum_l; iswalpha_l; iswblank_l; iswcntrl_l; iswdigit_l; iswgraph_l;
    iswlower_l; iswprint_l; iswpunct_l; iswspace_l; iswupper_l; iswxdigit_l;
    iswctype_l; wctype_l; wctrans_l; towctrans_l; towlower_l; towupper_l;

    /* <wchar.h> — musl src/string wcs and wmem families + src/multibyte (btowc/wctob/
     * mbsrtowcs/...) + src/stdlib/{wcstol,wcstod}.c + src/time/wcsftime.c,
     * all compiled in musl_wchar_objs (mbsinit/mbrtowc/wcrtomb/wctomb come from
     * musl_multibyte_objs but <wchar.h> now declares them as public API, so
     * they are listed here to become GLOBAL — libc.map's local: otherwise
     * hides them). wcstoimax/wcstoumax are also declared in <inttypes.h>.
     * The wide-char stdio family below (wprintf/fwprintf/swprintf/wscanf/.../
     * fgetwc/fputwc/fgetws/fputws/ungetwc/fwide/getwc/getwchar/putwc/putwchar/
     * open_wmemstream) is compiled in musl_stdio_objs — its deps (isw families,
     * wcsnlen, btowc/wctob + __c_locale) are now satisfied by musl_wchar_objs +
     * musl_time_objs. Only the *_unlocked and __isoc99_* internal aliases stay
     * hidden (not declared in <wchar.h>, no consumer — same rule as narrow stdio).
     * wcscoll/wcsxfrm/wcscoll_l/wcsxfrm_l are built + exported by the <locale.h>
     * block below (musl_locale_objs); wcsftime_l is a weak_alias in wcsftime.c
     * with no header-decl consumer (hidden). */
    wcscpy; wcsncpy; wcscat; wcsncat; wcscmp; wcsncmp; wcschr; wcsrchr;
    wcscspn; wcsspn; wcspbrk; wcstok; wcslen; wcsnlen; wcsstr; wcswcs;
    wcscasecmp; wcsncasecmp; wcscasecmp_l; wcsncasecmp_l;
    wcsdup; wcpcpy; wcpncpy;
    wmemchr; wmemcmp; wmemcpy; wmemmove; wmemset;
    btowc; wctob; mblen; mbrlen; mbstowcs; wcstombs; mbsrtowcs; wcsrtombs;
    mbsnrtowcs; wcsnrtombs; mbtowc; wctomb;
    mbsinit; mbrtowc; wcrtomb;
    wcstof; wcstod; wcstold; wcstol; wcstoul; wcstoll; wcstoull;
    wcstoimax; wcstoumax;
    wcsftime;
    /* wide-char stdio (musl_stdio_objs, declared in <wchar.h>) */
    fwide; wprintf; fwprintf; swprintf; vwprintf; vfwprintf; vswprintf;
    wscanf; fwscanf; swscanf; vwscanf; vfwscanf; vswscanf;
    fgetwc; getwc; getwchar; fputwc; putwc; putwchar;
    fgetws; fputws; ungetwc; open_wmemstream;

    /* <sys/ioctl.h> */
    ioctl;

    /* <sys/poll.h> */
    poll;
    ppoll;

    /* <sys/epoll.h> */
    epoll_create; epoll_create1; epoll_ctl; epoll_wait; epoll_pwait;

    /* <sys/eventfd.h> */
    eventfd;

    /* <sys/timerfd.h> */
    timerfd_create; timerfd_settime;

    /* <sys/signalfd.h> */
    signalfd;

    /* <sys/inotify.h> — musl src/linux/inotify.c (kernel: kernel/bsd/inotify.c) */
    inotify_init; inotify_init1; inotify_add_watch; inotify_rm_watch;

    /* <sys/mount.h> */
    mount;

    /* <sys/utsname.h> */
    uname;

    /* <sys/syscall.h> — musl src/misc/syscall.c. The indirect-syscall primitive
     * (syscall(number, ...)); used by libc++'s <atomic> wait/wake via
     * syscall(SYS_futex, ...). A thin wrapper over the arch __syscallN; exported
     * because cross-built runtimes (libc++abi __cxa_guard_acquire uses it for
     * futex-based once-init) link against it. */
    syscall;

    /* <sys/random.h> */
    getrandom; getentropy;
    arc4random_buf; arc4random_uniform;

    /* <sys/process.h> — execve/fork/spawn are hand-written (user/lib);
     * execl/execle/execlp/execv/execvp/execvpe/fexecve come from musl
     * src/process (musl_process_objs). execvp.c also weak_aliases execvpe. */
    execl; execle; execlp; execv; execve; execvp; execvpe; fexecve;
    fork; getpgid; getsid; setpgid; setsid; spawn; setuid; setgid;

    /* <sys/ipc.h> — 微内核 IPC 用户态入口 */
    ipc_msg; ipc_msg_fd; ipc_msg_resp; ipc_notify; ipc_notify_fd;
    ipc_recv; ipc_req; ipc_resp;

    /* <sys/irq.h> */
    irq_bind;

    /* <sys/pci.h> */
    pci_dev_info_get;

    /* <sys/device.h> */
    device_register; device_register_shm; device_set_meta;

    /* <unistd.h> */
    wait_dev_ready;

    /* 事实 ABI：musl crt1/Scrt1 跨 .so 调用 */
    __libc_start_main;

    /* musl-compatible public ABI used by fused libc internals */
    prctl; strnlen;

    /* Bootstrap stages are reached through find_sym() before normal dynamic
       linking is available, so both must remain in ldso's dynsym. */
    __dls2b;
    __dls3;

    /* <dlfcn.h> — dlopen/dladdr/dl_iterate_phdr from fused dynlink.c; dlsym/dlclose/dlinfo/dlerror from musl_dl_objs (dlerror.c reads musl struct pthread's dlerror_buf/flag at %fs:0, now that musl_pthread provides the full layout). */
    dlopen; dlsym; dlclose; dlerror; dladdr; dlinfo; dl_iterate_phdr;

local:
    *;
};
